import{_ as e,o as i,c as s,a4 as t}from"./chunks/framework.Bzo08Beo.js";const k=JSON.parse('{"title":"The analysis workflow","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workflow.md","filePath":"guide/workflow.md","lastUpdated":null}'),r={name:"guide/workflow.md"};function n(o,a,l,h,p,c){return i(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="The-analysis-workflow" tabindex="-1">The analysis workflow <a class="header-anchor" href="#The-analysis-workflow" aria-label="Permalink to &quot;The analysis workflow {#The-analysis-workflow}&quot;">​</a></h1><p>The image processing and Fourier analysis steps solve different problems. Inspect the output of each before moving on.</p><h2 id="1.-Prepare-a-periodic-region" tabindex="-1">1. Prepare a periodic region <a class="header-anchor" href="#1.-Prepare-a-periodic-region" aria-label="Permalink to &quot;1. Prepare a periodic region {#1.-Prepare-a-periodic-region}&quot;">​</a></h2><p>Start with one cell or an integer number of repeated cells. Remove text, axes, borders, and colorbar ticks. An FFT periodically repeats the whole input rectangle; a mismatch across its edges introduces additional frequencies.</p><p>For a sheared image, <code>FA.shear_image(img, θ)</code> applies an image warp and <code>FA.crop_transparent_border_of_image</code> crops its transparent borders using center-line scans. This helper is designed for the supplied image workflow, rather than arbitrary segmentation. Inspect the crop before treating it as a periodic cell.</p><h2 id="2.-Recover-scalar-values" tabindex="-1">2. Recover scalar values <a class="header-anchor" href="#2.-Recover-scalar-values" aria-label="Permalink to &quot;2. Recover scalar values {#2.-Recover-scalar-values}&quot;">​</a></h2><p>Pass an RGB image, a top-to-bottom colorbar column, and the colorbar&#39;s numeric limits to <code>FA.map_image_to_data</code>. It compares each pixel with the colorbar using <code>colordiff</code> and assigns the value of the nearest color.</p><p>Digitization is approximate. Compression, antialiasing, illumination, a nonlinear colorbar, or a color map that repeats colors can change or invalidate the inferred values. Keep the original image and calibration with your result.</p><h2 id="3.-Inspect-the-spectrum" tabindex="-1">3. Inspect the spectrum <a class="header-anchor" href="#3.-Inspect-the-spectrum" aria-label="Permalink to &quot;3. Inspect the spectrum {#3.-Inspect-the-spectrum}&quot;">​</a></h2><p><code>FA.fft_power_analysis(data, τ)</code> returns a Boolean mask and the raw FFT. Despite its historical name, the selection heuristic uses Fourier <strong>amplitudes</strong>, not squared amplitudes. See <a href="./filtering.html">filtering &amp; accuracy</a>.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mask, F </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">fft_power_analysis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(data, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.02</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">retained_fraction </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(abs2, F[mask]) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(abs2, F)</span></span></code></pre></div><p>The fraction above is a separate diagnostic for a nonzero input; it is not the meaning of <code>τ</code>.</p><h2 id="4.-Store-a-compact-real-valued-model" tabindex="-1">4. Store a compact real-valued model <a class="header-anchor" href="#4.-Store-a-compact-real-valued-model" aria-label="Permalink to &quot;4. Store a compact real-valued model {#4.-Store-a-compact-real-valued-model}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">harmonics </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">extract_dominant_harmonics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(data, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.02</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">opdata </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">filter_principal_frequencies_for_fft_of_real_data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(harmonics)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">write_opdata_to_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(opdata, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;harmonics.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Extraction normalizes FFT coefficients by the total number of samples. Principal-frequency filtering keeps one member of each ordinary conjugate pair and puts the DC term last. The current reconstruction convention assumes that final DC tuple exists.</p><h2 id="5.-Evaluate-and-compare" tabindex="-1">5. Evaluate and compare <a class="header-anchor" href="#5.-Evaluate-and-compare" aria-label="Permalink to &quot;5. Evaluate and compare {#5.-Evaluate-and-compare}&quot;">​</a></h2><p>Use <code>FA.build_sheared_function_from_sinousoids(opdata, X, Y, θ)</code> to evaluate the model on arrays of Cartesian coordinates. <code>X</code> and <code>Y</code> should have the same shape and floating-point element type as the mode magnitudes.</p><p>Measure error on numeric values before applying a color map. <code>FA.create_image_from_data</code> independently rescales a nonconstant matrix to its own minimum and maximum, which can hide amplitude differences between reconstructions.</p><h2 id="What-this-workflow-establishes" tabindex="-1">What this workflow establishes <a class="header-anchor" href="#What-this-workflow-establishes" aria-label="Permalink to &quot;What this workflow establishes {#What-this-workflow-establishes}&quot;">​</a></h2><p>The tutorials test synthetic mode recovery, a synthetic colorbar calibration, and the implemented coordinate transform. They do not certify experimental image fidelity or the physical interpretation of a particular material&#39;s harmonic coefficients.</p>`,20)])])}const m=e(r,[["render",n]]);export{k as __pageData,m as default};
